INSERT INTO purpose VALUES('kernel-strata','entail::Entailment','enum','Carries the entailment dichotomy as data: the claim holds with a replayable derivation, or it is refuted by a checkable countermodel.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','entail::EntailmentCountermodel','struct','Carries the negative entailment evidence: a model of the whole query system that covers the query seeds while refuting one recorded goal atom.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','entail::EntailmentHolds','struct','Carries the decision of whether an entailment dichotomy is the positive branch.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','entail::EntailmentWitness','struct','Carries the positive entailment evidence: the strictness flag and the replayable forward derivation that covers every goal atom of the claim from the query seeds.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','entail::validate_entailment_countermodel','function','Checks an entailment countermodel against its claim by recomputing the query system and verifying the model covers the seeds, satisfies every clause, and refutes its recorded goal.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','entail::validate_entailment_witness','function','Checks an entailment witness against its claim by replaying its derivation over the recomputed query encoding, refusing a step that fails or a goal the replay leaves uncovered.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','horn::AtomCoverage','struct','Carries the decision of whether a stored model value covers a requested Horn atom.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','horn::ClauseIndex','struct','Names a base clause''s position in the documented compilation order, so an index means the same thing to the oracle, the validators and a reviewer.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','horn::ClauseTriviality','struct','Carries the decision of whether a clause is self-subsumed, its conclusion dominated by a same-variable body atom.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','horn::DerivationRoundLimit','struct','Holds the finite round limit for derivation extraction, the bound past which evidence is reported incomplete rather than trusted.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','horn::HornOffset','struct','Holds an atom offset in the shifted clause system, with checked addition and saturating subtraction that floors a below-body conclusion at zero rather than a negative gain.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','horn::HornShift','struct','Holds the upward shift applied to a represented Horn clause family, the minimum of the query system being the unit shift.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','horn::MaxGain','struct','Holds the maximum gain of a shifted Horn clause system, zero for a system with no clauses.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','horn::ModelIsInfinite','struct','Carries the decision of whether a model value is infinite.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','horn::ModelValue','enum','Holds a value of the model domain, a finite maximum or infinity, standing for the downward-closed atom set of a variable.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','horn::SaturationBound','struct','Holds the small-model saturation bound, the value past which a finite component is read as infinite.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','horn::SaturationDiverged','struct','Carries the decision of whether saturation drove some component out of the finite range.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','level::Level','struct','Holds a universe level in its canonical form, the finite join of a constant part and one offset per variable, so that canonical-form identity is the kernel''s level-equality oracle.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','level::LevelConstant','struct','Holds the canonical constant component of a universe level, advanced only by a successor that refuses at the ceiling rather than saturating.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','level::LevelError','enum','Surfaces an offset or constant that stepped past the representable range as a typed error rather than a saturation that would identify distinct levels.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','level::LevelIsZero','struct','Carries the decision of whether a canonical level is the zero level.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','level::LevelOffset','struct','Holds a finite successor count used as a level atom offset, advanced only by a successor that refuses at the ceiling rather than saturating.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','level::LevelValue','struct','Holds the natural value produced by evaluating a level under a valuation, with checked u128-wide arithmetic that overflows rather than wraps.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','level::LevelVar','struct','Names a level variable as an index into the owning declaration''s prenex level context, the same index space the landmark-poset encoding reuses for declared constants.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','level::LevelVarIndex','struct','Indexes a level variable into the owning declaration''s prenex level context.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','order::AtomBound','struct','Records one step of a domination witness: the variable both atoms range over and the exact offsets of the left and dominating right atoms.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','order::ConstantBound','enum','Names what bounds the left level''s constant part within the right level: the right level''s own constant part, or its atom over a named variable.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','order::EvidenceError','enum','Names exactly why a piece of order evidence fails to check against its levels.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','order::LeqRefutation','struct','Carries the checkable refutation of a claimed order: a concrete counter-valuation under which the claimed order fails, absent variables reading as zero.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','order::LeqWitness','struct','Carries the checkable domination witness for a claimed order, one bound per left atom in ascending variable order plus the bound on the left constant part.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','order::OrderComparison','struct','Carries the truth value returned by the boolean face of the free order oracle.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','order::OrderShift','struct','Holds the upward shift a comparison mode applies to the left side, one for the strict order and zero for the non-strict one, wide enough that a ceiling shift cannot overflow.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','order::Strictness','struct','Names whether an order query is strict or non-strict, the one place the two comparison modes differ.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','order::validate_refutation','function','Checks a refutation against its two levels by direct evaluation, refusing a valuation that does not refute or that overflows evaluation.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','order::validate_witness','function','Checks a domination witness against its two levels by recomputing every claimed bound and the constant bound, refusing a missing, stray, mismatched or insufficient bound.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::AdmissionOutcome','enum','Carries the loop-checking dichotomy as data: the constraints admit with their consistency certificate, or they loop with a pumping witness.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::ConsistencyValue','struct','Holds a natural value in a consistency homomorphism certificate.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::ConsistencyWitness','struct','Carries the positive admission evidence: an explicit homomorphism into the naturals, one value per declared variable, under which every declared constraint holds.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::ConstraintIndex','struct','Names a constraint''s position in the declared list.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::ConstraintRelation','enum','Names the declared relation of a landmark constraint: left at most right, or left equal to right.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::Derivation','struct','Holds a replayable forward derivation, a sequence of clause-instance applications whose predecessor clauses stay implicit.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::DerivationStep','struct','Records one step of a replayable forward derivation: the base clause by index and the upward shift it fires at.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::EvidenceSubject','enum','Names which generator an evidence position refers to: the pinned bottom generator that carries constants, or an ordinary level variable.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::LandmarkConstraint','struct','Holds one declared landmark constraint over variable-only levels, constructed only through the checked constructors that enforce the variable-only restriction.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::LandmarkPoset','struct','Holds an admitted landmark poset: the declared constraints, their compiled clause system fixed at admission and reused by every query, and the consistency certificate admission produced.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::LoopWitness','struct','Carries the negative admission evidence: a nonempty variable set and shift with a replayable pumping derivation, so no homomorphism into the naturals exists.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::ModelRefusal','struct','Carries a proposed model the consistency validator refuses, with the declared constraints handed back so the caller admits them by loop-checking.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::PosetError','enum','Surfaces the failures of poset construction and the decision procedures, so the kernel never panics on poset data.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::PosetEvidenceError','enum','Names exactly why a piece of poset or entailment evidence fails to check.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::validate_consistency','function','Checks a consistency witness against its constraints by direct evaluation, refusing a missing assignment or a constraint that fails under the witness.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('kernel-strata','poset::validate_loop_witness','function','Checks a loop witness by confirming its member set is nonempty and its pumping derivation replays to cover every target, refusing a forged or incomplete certificate.',NULL,'fits','sound',NULL);
